('adp_noun_0', 'adp', 'noun', 0, 'Adenosine diphosphate, a nucleotide composed of adenine, ribose, and two phosphate groups, generated by the hydrolysis of ATP and acting as a central intermediate in cellular energy transfer and metabolic regulation.', '["adenosine diphosphate", "ADP molecule", "nucleotide"]', '["ATP", "adenosine triphosphate"]', '["nucleotide", "biomolecule"]', '["magnesium ADP complex", "ADP ribose"]', '["ATP and ADP", "ADP levels", "ADP concentration", "ADP dependent"]', '{"noun_forms": ["ADP level", "ADP concentration", "ADP molecule"], "verb_forms": [], "adjective_forms": ["ADP dependent", "ADP mediated"], "adverb_forms": []}', '["ATP donates a phosphate group to become ADP during many energy requiring biochemical reactions.", "High ADP levels stimulate oxidative phosphorylation in the mitochondria."]', 'science', 'BS', 2701, 37803, NULL, 'opengloss-v1.1'),
('adp_noun_1', 'adp', 'noun', 1, 'An abbreviation designating a formal academic or professional program whose title includes terms such as advanced, accelerated, or academic combined with development, diploma, or degree program, especially in institutional or policy documentation.', '["degree program", "development program", "academic program"]', '["informal program"]', '["program", "initiative"]', '["accelerated degree program", "assistant development program"]', '["ATP and ADP", "ADP levels", "ADP concentration", "ADP dependent"]', '{"noun_forms": ["ADP level", "ADP concentration", "ADP molecule"], "verb_forms": [], "adjective_forms": ["ADP dependent", "ADP mediated"], "adverb_forms": []}', '["The ADP allows undergraduates to complete a bachelor’s and master’s degree in five years.", "Faculty participation in the ADP is optional but strongly encouraged."]', 'science', 'BS', 2701, 37803, NULL, 'opengloss-v1.1'),
('adp_noun_2', 'adp', 'noun', 2, 'An abbreviation for Automatic Data Processing, a multinational corporation that provides payroll processing, human resources management, and other business outsourcing services, or by extension its payroll and HR platforms.', '["payroll provider", "HR services firm", "outsourcing company"]', '["in house payroll"]', '["company", "service provider"]', '["payroll processing service", "HR outsourcing service"]', '["ATP and ADP", "ADP levels", "ADP concentration", "ADP dependent"]', '{"noun_forms": ["ADP level", "ADP concentration", "ADP molecule"], "verb_forms": [], "adjective_forms": ["ADP dependent", "ADP mediated"], "adverb_forms": []}', '["The company outsourced its payroll to ADP to streamline compliance and reporting.", "ADP offers cloud based tools for managing employee benefits and time tracking."]', 'science', 'BS', 2701, 37803, NULL, 'opengloss-v1.1')
